/* eslint-disable @typescript-eslint/explicit-function-return-type */
/* eslint-disable no-restricted-globals */
/* eslint-disable jsdoc/require-jsdoc */
/* eslint-disable @typescript-eslint/naming-convention */
/* eslint-disable import-x/no-named-as-default-member -- Bowser.parse is the intended API */
import Bowser from 'bowser';

export enum PlatformType {
  // React Native or Nodejs
  NonBrowser = 'nodejs',
  // MetaMask Mobile in-app browser
  MetaMaskMobileWebview = 'in-app-browser',
  // Desktop Browser
  DesktopWeb = 'web-desktop',
  // Mobile Browser
  MobileWeb = 'web-mobile',
  // ReactNative
  ReactNative = 'react-native',
}

const NATIVE_METAMASK_EIP6963_RDNS = new Set([
  'io.metamask',
  'io.metamask.mobile',
  'io.metamask.flask',
]);

function isNotBrowser(): boolean {
  if (typeof window === 'undefined') {
    return true;
  }
  if (!window?.navigator) {
    return true;
  }
  return navigator?.product === 'ReactNative';
}

function isReactNative(): boolean {
  // Modern Hermes-based RN: window is undefined, but global.navigator.product is set.
  // This check must come first so getPlatformType() resolves to ReactNative rather
  // than NonBrowser when isNotBrowser() would otherwise catch this case.
  if (
    typeof global !== 'undefined' &&
    global?.navigator?.product === 'ReactNative'
  ) {
    return true;
  }

  // Legacy RN environments where window === global
  const hasWindowNavigator =
    typeof window !== 'undefined' && window.navigator !== undefined;

  return hasWindowNavigator && window.navigator?.product === 'ReactNative';
}

function isMetaMaskMobileWebView(): boolean {
  return (
    typeof window !== 'undefined' &&
    // @ts-expect-error ReactNativeWebView should be defined
    Boolean(window.ReactNativeWebView) &&
    Boolean(window.navigator.userAgent.endsWith('MetaMaskMobile'))
  );
}

function isMobile(): boolean {
  const browser = Bowser.parse(window.navigator.userAgent);
  return (
    browser?.platform?.type === 'mobile' || browser?.platform?.type === 'tablet'
  );
}

export function getPlatformType(): PlatformType {
  if (isReactNative()) {
    return PlatformType.ReactNative;
  }
  if (isNotBrowser()) {
    return PlatformType.NonBrowser;
  }
  if (isMetaMaskMobileWebView()) {
    return PlatformType.MetaMaskMobileWebview;
  }
  if (isMobile()) {
    return PlatformType.MobileWeb;
  }
  return PlatformType.DesktopWeb;
}

/**
 * Check if MetaMask extension is installed
 *
 * @returns True if extension is installed, false otherwise
 */
export function isMetamaskExtensionInstalled(): boolean {
  if (typeof window === 'undefined') {
    return false;
  }
  // @ts-expect-error ethereum should be defined
  return Boolean(window.ethereum?.isMetaMask);
}

export function isSecure(): boolean {
  const platformType = getPlatformType();
  return isReactNative() || platformType === PlatformType.MobileWeb;
}

// Immediately start MetaMask detection when module loads
const detectionPromise: Promise<boolean> = (async () => {
  const pt = getPlatformType();
  if (pt === PlatformType.NonBrowser || pt === PlatformType.ReactNative) {
    return Promise.resolve(false);
  }

  return new Promise((resolve) => {
    const providers: any[] = [];
    // Keep the same window reference if the global is torn down before timeout.
    const targetWindow = window;

    const handler = (event: any) => {
      if (event?.detail?.info?.rdns) {
        providers.push(event.detail);
      }
    };

    targetWindow.addEventListener('eip6963:announceProvider', handler);
    targetWindow.dispatchEvent(new Event('eip6963:requestProvider'));

    setTimeout(() => {
      // The window/global can be torn down before this timeout fires (e.g. test
      // environment teardown, SPA navigation), which makes the captured
      // reference's methods unavailable. Guard so the timer never throws an
      // unhandled exception; fall back to "no extension" when detection can't
      // complete.
      try {
        if (typeof targetWindow?.removeEventListener === 'function') {
          targetWindow.removeEventListener('eip6963:announceProvider', handler);
        }

        const hasMetaMask = providers.some(
          (provider) =>
            typeof provider?.info?.rdns === 'string' &&
            NATIVE_METAMASK_EIP6963_RDNS.has(provider.info.rdns),
        );

        resolve(hasMetaMask);
      } catch {
        resolve(false);
      }
    }, 300); // default timeout
  });
})();

export async function hasExtension(): Promise<boolean> {
  return detectionPromise;
}
